    bg: Optional[str] = None
    bold = dim = italic = underline = False
    last = 0

    def push(s: str) -> None:
        if not s:
            return
        cls = " ".join(c for c, on in (("a-b", bold), ("a-d", dim), ("a-i", italic), ("a-u", underline)) if on)
        style: Dict[str, str] = {}
