@dataclass(frozen=True)
class Tokens:
    """One theme's colours. Names follow tokens.css (``--text-2`` → ``text_2``)."""

    name: str
    dark: bool
    canvas: str
    chrome: str
    raised: str
    raised_2: str
    inset: str
    hair: str
    hair_2: str
    hair_3: str
    fill_1: str
    fill_2: str
    fill_3: str
    text: str
    text_2: str
    text_3: str
    text_4: str
    accent: str
    accent_2: str
    accent_ink: str
    accent_text: str
    accent_wash: str
    accent_line: str
    accent_ring: str
    ok: str
    ok_wash: str
    err: str
    err_wash: str
    info: str
    info_wash: str
    warn: str
    warn_wash: str
    plan: str
    plan_wash: str
    think: str
    think_wash: str
    diff_add: str
    diff_add_hl: str
    diff_del: str
    diff_del_hl: str
    scrim: str
    selection: str
    glass: str
    glass_2: str
    edge_hi: str
    cm_comment: str
    cm_keyword: str
    cm_string: str
    cm_number: str
    cm_function: str
    cm_type: str
    cm_property: str
    cm_tag: str
    cm_regex: str
    cm_punct: str
    ansi_black: str
    ansi_red: str
    ansi_green: str
    ansi_yellow: str
    ansi_blue: str
    ansi_magenta: str
    ansi_cyan: str
    ansi_white: str
    ansi_bright_black: str
    ansi_bright_red: str
    ansi_bright_green: str
    ansi_bright_yellow: str
    ansi_bright_blue: str
    ansi_bright_magenta: str
    ansi_bright_cyan: str
    ansi_bright_white: str

    def color(self, name: str) -> QColor:
        """A token as a QColor (``rgba()`` strings included)."""
        return qcolor(getattr(self, name))

    def ansi(self, var: str) -> Optional[str]:
        """``var(--ansi-bright-red)`` (as lib/ansi.py emits) → the colour string, else None."""
        if var.startswith("var(--ansi-") and var.endswith(")"):
            return getattr(self, "ansi_" + var[len("var(--ansi-") : -1].replace("-", "_"), None)
        return None


