        self.cwd = str(opts.get("cwd") or (rec[0] if rec else "") or home())
        self.git: Optional[Json] = None
        self.branches: List[str] = []
        self.busy = False
        self._git_timer = QTimer(self)
        self._git_timer.setSingleShot(True)
