    # ---- the commands
    def _actions(self) -> List[Cmd]:
        s = store
        win = self.window_
        active_id = s.active_id
        cfg = s.config or {}
        dark = cfg.get("theme") == "dark"

        def panel(tab: str) -> Callable[[], None]:
