            self.group.addButton(r)
            lay.addWidget(r)
            self.rows[str(m["id"])] = r
        if value in self.rows:
            self.rows[value].setChecked(True)
        elif self.rows:
            first = next(iter(self.rows))
            self.rows[first].setChecked(True)
