    # ---- geometry
    def relayout(self) -> None:
        host = self.parentWidget()
        if host is None or self._closing:
            return
        self.setGeometry(host.rect())
        w, h = self.width(), self.height()
        fw = min(self._width, max(320, w - 40))
        top = int(h * 0.09)
