        ml.addLayout(top)
        if st == "running":
            what = a.get("lastToolSummary") or (f"Using {a['lastToolName']}" if a.get("lastToolName") else "Thinking…")
        elif st in ("error", "blocked"):
            what = str(a.get("error") or "").split("\n")[0]
