def make_tool_card(
    item: ToolItem, ctx: ToolCtx, perm: Optional[dict] = None, parent: Optional[QWidget] = None
) -> QWidget:
    """``ToolCard(item, ctx, perm)`` from tool_card.py, or a one-line stand-in while that module is being written."""
