            log('server', server['version'], 'is older than the installed', installed, '- replacing it')
            quit_server(server['url'])
            deadline = time.time() + 8
            while time.time() < deadline:
                time.sleep(0.25)
                try:
                    os.kill(server['pid'], 0)
                except OSError:
                    break
