            try:
                gi.require_version('WebKit2', '4.1')
            except ValueError:
                gi.require_version('WebKit2', '4.0')
        except Exception as e:
            log('gtk backend unavailable', e)
            backend = 'qt'
    sys.exit(run_gtk(server, proc) if backend == 'gtk' else run_qt(server, proc))

if __name__ == '__main__':
    main()
