  return (
    <div className="comment-editor">
      <textarea
        className="textarea"
        autoFocus
        rows={2}
        value={text}
        placeholder="Leave a note for Claude about this line…"
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) onSave(text);
