    },
    [cwd], // eslint-disable-line react-hooks/exhaustive-deps
  );

  useEffect(() => {
    if (fileOpen) openTab(fileOpen.path, fileOpen.line);
  }, [fileOpen?.nonce]); // eslint-disable-line react-hooks/exhaustive-deps

