            setTreeNonce((n) => n + 1);
          }}
        >
          <RefreshCw size={13} />
        </button>
      </div>
      <div className="files-body">
        {st.showTree && (
          <div className="tree">
            <HistoryCtx.Provider value={{ cwd, map: history }}>
