/* ================================================================ side panel
   Lives on the chrome surface like the sidebar. Tabs are text with a sliding underline;
   each tab has one toolbar row of borderless controls. */

.panel {
  flex: 0 1 auto;
  min-width: 300px;
  /* Never wider than the conversation in a small window, never above 40% of a big one. */
  max-width: max(300px, min(40vw, calc(100vw - 760px)));
  display: flex;
  flex-direction: column;
  background: var(--canvas);
  container-type: inline-size;
}
/* The panel gives way before the conversation does: in a narrow window it shrinks (down to 300px)
   instead of pushing past the window edge. */
.panel-shell {
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  min-height: 0;
  background: var(--chrome);
}

.panel-tabs {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  gap: 2px;
  height: var(--header-h);
  padding: 0 8px 0 10px;
  box-shadow: inset 0 -1px 0 var(--hair);
  overflow-x: auto;
  scrollbar-width: none;
}
.panel-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 8px;
  border-radius: var(--r-2);
  font-size: var(--fs-ui);
  color: var(--text-3);
  white-space: nowrap;
  transition: color var(--t-fast), background var(--t-fast);
}
.panel-tab:hover {
  color: var(--text);
  background: var(--fill-1);
}
.panel-tab.on {
  color: var(--text);
  font-weight: 550;
}
.panel-tab-ico {
  flex: none;
  opacity: 0.85;
}
.panel-tab.on .panel-tab-ico {
  opacity: 1;
}
.panel-ink {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: var(--text);
  transition: transform var(--t-panel) var(--ease), width var(--t-panel) var(--ease);
  pointer-events: none;
  z-index: 1;
}
.tab-count {
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: var(--fill-3);
  color: var(--text);
  font-size: 10.5px;
  font-weight: 600;
  display: grid;
  place-items: center;
}
/* In a narrow panel only the chosen tab keeps its name; the others are icons with tooltips. The name
   grows in and the ink follows, so switching tabs reads as one movement. */
@container (max-width: 759px) {
  .panel-tab:not(.on) .panel-tab-label {
    display: none;
  }
  .panel-tab:not(.on) {
    width: 34px;
    justify-content: center;
    padding: 0;
  }
  .panel-tab.on {
    padding: 0 10px 0 8px;
    animation: tab-name var(--t-panel) var(--ease);
  }
}
@keyframes tab-name {
  from {
    opacity: 0.4;
  }
}

.panel-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.panel-body > * {
  flex: 1;
  min-height: 0;
}
.panel-keep {
  flex-direction: column;
  min-height: 0;
}
.panel-keep > * {
  flex: 1;
  min-height: 0;
}

.panel-toolbar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 42px;
  padding: 6px 10px 6px 12px;
  box-shadow: inset 0 -1px 0 var(--hair);
  overflow-x: auto;
  scrollbar-width: none;
  font-size: var(--fs-small);
}
.panel-toolbar .btn.sm {
  height: 26px;
}

.panel .empty {
  padding: 40px 28px;
}

/* ---------------------------------------------------------------- changes */

.changes {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.changes-bar {
  gap: 6px;
}
.changes-scope {
  font-weight: 550;
  color: var(--text);
  white-space: nowrap;
}
.select-btn.ghost-select {
  height: 26px;
  max-width: 200px;
  padding: 0 6px 0 8px;
  background: transparent;
  box-shadow: none;
  font-weight: 550;
}
.select-btn.ghost-select:hover {
  background: var(--fill-2);
}
.changes-stat {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: 4px;
  font-size: var(--fs-small);
  white-space: nowrap;
}
.changes-summary {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: var(--fs-small);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.commit-box {
  flex: none;
  display: grid;
  gap: 8px;
  padding: 12px;
  box-shadow: inset 0 -1px 0 var(--hair);
  animation: rise var(--t-med) var(--ease);
}
.changes-files {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 0 24px;
  display: grid;
  align-content: start;
}
/* Files read as one continuous document: sticky headers, hairlines between files, no boxes. */
.cfile {
  min-width: 0;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 0 8px 0 6px;
  background: var(--chrome);
  font-size: var(--fs-small);
}
.cfile.open .cfile-head {
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head .icon-btn {
  opacity: 0;
  transition: opacity var(--t-fast);
}
.cfile-head:hover .icon-btn,
.cfile-head .icon-btn:focus-visible {
  opacity: 1;
}
.cfile-toggle {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 4px;
  text-align: left;
  border-radius: var(--r-2);
}
.cfile-toggle > svg {
  flex: none;
  color: var(--text-3);
  transition: transform var(--t-med) var(--ease);
}
.cfile-name {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
}
.cfile-dir {
  font-family: var(--font-mono);
  font-size: 11.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  direction: rtl;
  text-align: left;
}
.fstat {
  flex: none;
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 650;
}
.fstat.s-M {
  color: var(--text-2);
  background: var(--fill-2);
}
.fstat.s-A,
.fstat.s-U {
  color: var(--ok);
  background: var(--ok-wash);
}
.fstat.s-D {
  color: var(--err);
  background: var(--err-wash);
}
.fstat.s-R {
  color: var(--info);
  background: var(--info-wash);
}
.cfile-body .diff {
  border-radius: 0;
  max-height: none;
  box-shadow: none;
  background: var(--canvas);
}
.cfile-body .diff-grid {
  padding: 4px 0 8px;
}
.cfile-note {
  padding: 12px 14px;
  font-size: var(--fs-small);
}
.notes-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--raised);
  box-shadow: inset 0 1px 0 var(--hair-2);
  color: var(--text);
  font-size: var(--fs-small);
  animation: rise var(--t-med) var(--ease);
}

/* ---------------------------------------------------------------- files */

.files {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.files-body {
  flex: 1;
  min-height: 0;
  display: flex;
}
.tree {
  width: 212px;
  flex: none;
  overflow: auto;
  padding: 6px 6px 18px;
  box-shadow: inset -1px 0 0 var(--hair);
  font-size: 12.5px;
}
.tree-row {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  height: 26px;
  padding-right: 6px;
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
  white-space: nowrap;
  transition: background var(--t-fast), color var(--t-fast);
}
.tree-row:hover {
  background: var(--fill-1);
  color: var(--text);
}
.tree-row.on {
  background: var(--fill-2);
  color: var(--text);
}
.tree-row svg {
  flex: none;
}
.tree-dir-ico,
.tree-file-ico {
  color: var(--text-3);
}
.tree-row > .lucide-chevron-right {
  color: var(--text-4);
  transition: transform var(--t-fast) var(--ease);
}
.tree-err {
  font-size: 11.5px;
  color: var(--err);
  padding: 2px 6px;
}
.files-editor {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background: var(--canvas);
}
.ftabs {
  flex: none;
  display: flex;
  gap: 2px;
  padding: 6px 6px 0;
  overflow-x: auto;
  scrollbar-width: none;
  background: var(--chrome);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.ftab {
  display: flex;
  align-items: center;
  flex: none;
  border-radius: var(--r-2) var(--r-2) 0 0;
  font-size: 12px;
  color: var(--text-3);
  transition: color var(--t-fast), background var(--t-fast);
}
.ftab:hover {
  color: var(--text);
}
.ftab.on {
  background: var(--canvas);
  color: var(--text);
  box-shadow: 0 0 0 1px var(--hair);
  clip-path: inset(-1px -1px 0 -1px);
}
.ftab-main {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 4px 0 12px;
  font-family: var(--font-mono);
  font-size: 12px;
}
.ftab-x {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  margin-right: 5px;
  border-radius: 4px;
  color: var(--text-3);
  opacity: 0;
  transition: opacity var(--t-fast), background var(--t-fast);
}
.ftab:hover .ftab-x,
.ftab.on .ftab-x {
  opacity: 1;
}
.ftab-x:hover {
  background: var(--fill-2);
  color: var(--text);
}
.dirty-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--text-2);
}
.editor {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
.editor .cm-editor {
  height: 100%;
}
.editor .cm-editor.cm-focused {
  outline: none;
}
.img-preview {
  flex: 1;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  padding: 24px;
  overflow: auto;
}
.img-preview img {
  max-width: 100%;
  max-height: 70vh;
  border-radius: var(--r-2);
  box-shadow: var(--shadow-card);
  background: repeating-conic-gradient(var(--fill-2) 0 25%, transparent 0 50%) 0 0 / 16px 16px;
}

/* ---------------------------------------------------------------- terminal */

.terms {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.ttab {
  display: inline-flex;
  align-items: center;
  flex: none;
  border-radius: var(--r-2);
  font-size: 12px;
  color: var(--text-3);
  transition: color var(--t-fast), background var(--t-fast);
}
.ttab:hover {
  color: var(--text);
}
.ttab button:first-child {
  height: 26px;
  padding: 0 4px 0 9px;
  font-family: var(--font-mono);
}
.ttab.on {
  background: var(--fill-2);
  color: var(--text);
}
.ttab.exited {
  opacity: 0.55;
}
.ttab-x {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  margin-right: 4px;
  border-radius: 4px;
}
.ttab-x:hover {
  background: var(--fill-2);
}
.term-host {
  flex: 1;
  min-height: 0;
  background: var(--chrome);
  padding: 8px 4px 4px 12px;
}
.xterm-host {
  height: 100%;
}
.xterm-host .xterm-viewport {
  background: transparent !important;
}
.xterm-host .xterm .scrollbar.vertical {
  width: 10px !important;
}
.xterm-host .xterm .scrollbar .slider {
  left: 3px !important;
  width: 5px !important;
  border-radius: 3px;
  background: var(--fill-3) !important;
}
.xterm-host .xterm .scrollbar .slider:hover,
.xterm-host .xterm .scrollbar .slider.active {
  background: var(--hair-3) !important;
}

/* ---------------------------------------------------------------- preview */

.preview {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.url-bar {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
}
.url-bar .input {
  height: 28px;
  font-size: 12px;
}
.preview .chips {
  padding: 8px 12px;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.preview-frame {
  flex: 1;
  min-height: 0;
  width: 100%;
  border: none;
  background: #fff;
}

/* ---------------------------------------------------------------- tasks & session info */

.tasks-panel,
.info-panel {
  overflow-y: auto;
  padding: 4px 16px 24px;
}
.ps {
  display: grid;
  gap: 10px;
  padding: 16px 0 18px;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.ps:last-child {
